 if(id==='D5.N1000000'){mode=chooseMode(id,s,['compare','round','sequence','fraction_million']);if(mode==='round'){let n=R(100000,999999),unit=pick([1000,10000,100000]),ans=Math.round(n/unit)*unit;return depth(Q(`Bundarkan <b>${n}</b> kepada ${unit.toLocaleString('en-US')} terdekat.`,ans,[N(Math.floor(n/unit)*unit,'round'),N(Math.ceil(n/unit)*unit,'round'),N(n,'round')],'Lihat digit penentu di sebelah kanan nilai tempat.','Tahun 5 · Membundar',true,true),id,mode,'symbolic','procedure',['round']);}if(mode==='sequence'){let n=R(100000,700000),step=pick([2500,5000,10000,25000]),ans=n+3*step;return depth(Q(`${n}, ${n+step}, ${n+2*step}, ?`,ans,[N(ans-step,'pattern'),N(ans+step,'pattern'),N(n+3,'pattern')],'Cari perubahan tetap antara nombor.','Tahun 5 · Pola Nombor',true,true),id,mode,'symbolic','reasoning',['pattern']);}if(mode==='fraction_million'){let f=pick([[1,2,500000],[1,4,250000],[3,4,750000],[1,5,200000]]);return depth(Q(`<b>${f[0]}/${f[1]}</b> daripada 1 000 000 ialah?`,f[2],[N(f[2]/10,'place'),N(f[1]*100000,'operation'),N(1000000-f[2],'fraction')],'Bahagi sejuta mengikut penyebut, kemudian darab pengangka.','Tahun 5 · Pecahan Sejuta',true,true),id,mode,'symbolic','application',['fraction']);}return previous.d5?.(id,s,shift);}
 if(id==='D5.PV1000000'){mode=chooseMode(id,s,['place','expanded','missing','compose']);let n=uniqueDigitNumber(6),st=String(n),pos=R(0,5),vals=[+st[0]*100000,+st[1]*10000,+st[2]*1000,+st[3]*100,+st[4]*10,+st[5]],ans=vals[pos];if(mode==='missing')return depth(Q(`${n} = ${vals.map((v,i)=>i===pos?'___':v).join(' + ')}<br>Nilai hilang?`,ans,[N(+st[pos],'digit_value'),N(ans+1000,'place'),N(Math.max(0,ans-1000),'place')],'Gunakan nilai tempat hingga ratus ribu.','Tahun 5 · Nilai Tempat',true,true),id,mode,'symbolic','reasoning',['place']);if(mode==='expanded')return depth(Q(`Cerakinkan <b>${n}</b>.`,vals.filter(v=>v).join(' + '),[N(st.split('').join(' + '),'digit_value'),N([...vals].reverse().join(' + '),'place'),N(`${n}+0`,'place')],'Tulis nilai sebenar setiap digit.','Tahun 5 · Cerakin',true,true),id,mode,'symbolic','procedure',['place']);if(mode==='compose')return depth(Q(`${vals.filter(v=>v).join(' + ')} = ?`,n,[N(Number(st.split('').reverse().join('')),'place'),N(vals.reduce((a,b)=>a+b,0)+1000,'place'),N(st.split('').map(Number).reduce((a,b)=>a+b,0),'digit_value')],'Gabungkan semua nilai tempat.','Tahun 5 · Bina Nombor',true,true),id,mode,'symbolic','procedure',['place']);return depth(Q(`Nilai digit <b>${st[pos]}</b> dalam <b>${n}</b>?`,ans,[N(+st[pos],'digit_value'),N(ans/10,'place'),N(ans*10,'place')],'Kenal pasti kedudukan digit.','Tahun 5 · Nilai Digit',true,true),id,mode,'symbolic','concept',['place']);}
 if(id==='D5.MUL'){mode=chooseMode(id,s,['two_digit','story','missing','estimate']);let a=R(100,999),b=R(11,25),ans=a*b;if(mode==='story')return depth(Q(`${b} kotak, ${a} unit setiap kotak. Jumlah unit?`,ans,[N(a+b,'operation'),N(ans+b,'fact'),N(ans-100,'place')],'Darab kuantiti seunit dengan bilangan kotak.','Tahun 5 · Darab dalam Situasi',true,true),id,mode,'story','application',['fact']);if(mode==='missing')return depth(Q(`___ × ${b} = ${ans}`,a,[N(b,'fact'),N(a+b,'operation'),N(a+100,'place')],'Bahagi hasil dengan faktor diketahui.','Tahun 5 · Faktor Hilang',true,true),id,mode,'symbolic','reasoning',['fact']);if(mode==='estimate'){let ea=Math.round(a/100)*100,eb=Math.round(b/10)*10,e=ea*eb;return depth(Q(`Anggaran munasabah bagi ${a} × ${b}?`,e,[N(ans,'estimate'),N(ea+eb,'estimate'),N(e+1000,'estimate')],'Bundarkan kedua-dua faktor untuk anggaran.','Tahun 5 · Anggaran Darab',true,true),id,mode,'symbolic','reasoning',['estimate']);}return depth(Q(`${a} × ${b} = ?`,ans,[N(a+b,'operation'),N(ans+10,'fact'),N(Math.round(ans/100)*100,'fact')],'Darab mengikut nilai tempat.','Tahun 5 · Darab Pelbagai Digit',true,true),id,mode,'symbolic','procedure',['fact','place']);}
 if(id==='D5.DIV'){mode=chooseMode(id,s,['two_digit','remainder','story','missing']);let d=pick([12,15,20,24,25]),q=R(12,80),rem=mode==='remainder'?R(1,d-1):0,total=d*q+rem,ans=rem?`${q} baki ${rem}`:q;if(mode==='story'){return depth(Q(`${d*q} risalah dibahagi sama rata kepada ${d} kelas. Setiap kelas?`,q,[N(d,'division'),N(q+5,'division'),N(q-5,'division')],'Bahagi jumlah dengan bilangan kelas.','Tahun 5 · Bahagi dalam Situasi',true,true),id,mode,'story','application',['division']);}if(mode==='missing')return depth(Q(`${d*q} ÷ ___ = ${q}`,d,[N(q,'division'),N(d+5,'division'),N(Math.max(1,d-5),'division')],'Gunakan operasi songsang.','Tahun 5 · Pembahagi Hilang',true,true),id,mode,'symbolic','reasoning',['division']);return depth(Q(`${total} ÷ ${d} = ?`,ans,[N(q,'division'),N(rem?`${q+1} baki ${rem}`:q+5,'division'),N(rem?`${q} baki ${Math.max(0,rem-1)}`:q-5,'division')],'Bahagi dengan pembahagi dua digit.','Tahun 5 · Bahagi Pelbagai Digit',true,true),id,mode,'symbolic','procedure',['division']);}
