 if(id==='D6.TIME'){mode=chooseMode(id,s,['zone_forward','zone_backward','zone_duration','zone_table']);let cities=[['Bandar A',8],['Bandar B',9],['Bandar C',4],['Bandar D',2]],a=pick(cities),b=pick(cities.filter(x=>x[0]!==a[0]));if(mode==='zone_forward'){const c=cities.filter(x=>x[1]>a[1]);if(c.length)b=pick(c);}if(mode==='zone_backward'){const c=cities.filter(x=>x[1]<a[1]);if(c.length)b=pick(c);}let hour=R(6,20),minute=pick([0,15,30,45]),delta=b[1]-a[1],target=((hour+delta)%24+24)%24,fmt=(h,m)=>`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`,ans=fmt(target,minute);let table=miniTable(['Bandar','Zon'],[[a[0],`UTC${a[1]>=0?'+':''}${a[1]}`],[b[0],`UTC${b[1]>=0?'+':''}${b[1]}`]]);if(mode==='zone_duration'){let dur=pick([2,3,4]),arrival=((target+dur)%24+24)%24,arr=fmt(arrival,minute);return depth(Q(`${table}Siaran bermula di ${a[0]} pada ${fmt(hour,minute)} dan berlangsung ${dur} jam. Waktu tamat di ${b[0]}?`,arr,[N(ans,'time'),N(fmt((arrival+1)%24,minute),'time'),N(fmt(((arrival-1)%24+24)%24,minute),'time')],'Tukar waktu mula ke zon destinasi, kemudian tambah tempoh.','Tahun 6 · Zon Masa Dua Langkah',true,true),id,mode,'table','reasoning',['time']);}return depth(Q(`${table}Apabila ${a[0]} menunjukkan ${fmt(hour,minute)}, waktu di ${b[0]}?`,ans,[N(fmt((target+1)%24,minute),'time'),N(fmt(((target-1)%24+24)%24,minute),'time'),N(fmt(hour,minute),'time')],`${b[0]} berbeza ${Math.abs(delta)} jam; ${delta>=0?'tambah':'tolak'} perbezaan zon.`,'Tahun 6 · Zon Masa',true,true),id,mode,'table','application',['time']);}
