function wrapBank(key,gradeFn,prefix){
 const prev=previous[key];
 banks[key]=function(id,s,shift){
   if(!String(id).startsWith(prefix))return prev?.(id,s,shift)||null;
   const q=gradeFn(id,s,shift);
   return q||prev?.(id,s,shift)||null;
 };
}
